        for (count, from) in everyPair(countInputs, fromInputs) {
            var portLanes = sentinel
            var referenceLanes = sentinel
            from.withUnsafeBufferPointer { source in
                portLanes.withUnsafeMutableBufferPointer { destination in
                    unsafe H.copy(
                        count: count,
                        from: source.baseAddress!,
                        to: destination.baseAddress!
                    )
                }
                referenceLanes.withUnsafeMutableBufferPointer { destination in
                    unsafe HighwayReference.copyF64(
                        count,
                        source.baseAddress!,
                        destination.baseAddress!
                    )
                }
            }
            mismatches.check(portLanes, referenceLanes, "count: \(count), from: \(describe(from))")
        }
        mismatches.record()
    }

